<script lang="ts">
 import StatusChip from '$lib/components/ui/StatusChip.svelte'; import type { ShareNetwork } from '$lib/types/shareNetwork'; import SelectionCheckbox from '$lib/components/ui/SelectionCheckbox.svelte';
 let { networks, deleting, onDelete, selectedIds, selectableIds, selectionDisabled, onToggleSelect, onToggleAll }: { networks: ShareNetwork[]; deleting: string | null; onDelete: (id: string, name: string) => Promise<void>; selectedIds: ReadonlySet<string>; selectableIds: ReadonlySet<string>; selectionDisabled: boolean; onToggleSelect: (id: string) => void; onToggleAll: () => void; } = $props(); const selectedCount = $derived([...selectedIds].filter((id) => selectableIds.has(id)).length);
</script>
<div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b border-line text-ink-2 text-xs uppercase tracking-wide"><th class="text-left py-3 pr-3"><SelectionCheckbox checked={selectableIds.size > 0 && selectedCount === selectableIds.size} indeterminate={selectedCount > 0 && selectedCount < selectableIds.size} disabled={selectionDisabled || selectableIds.size === 0} onclick={onToggleAll} ariaLabel="전체 선택" /></th><th class="text-left py-3 pr-6">이름</th><th class="text-left py-3 pr-6">상태</th><th class="text-left py-3 pr-6">Neutron 네트워크 ID</th><th class="text-left py-3 pr-6">서브넷 ID</th><th class="text-left py-3 pr-6">생성일</th><th class="text-right py-3">액션</th></tr></thead><tbody>{#each networks as net (net.id)}<tr class="resource-selection-surface border-b border-line/50 hover:bg-surface-sunken/30 transition-colors" data-selected={selectedIds.has(net.id)}><td class="py-3 pr-3"><SelectionCheckbox checked={selectedIds.has(net.id)} disabled={selectionDisabled} onclick={() => onToggleSelect(net.id)} ariaLabel={`${net.name || net.id} 선택`} /></td><td class="py-3 pr-6 font-medium text-ink-0">{#if net.name}<span>{net.name}</span>{:else}<span class="font-mono text-xs text-ink-2">{net.id.slice(0, 8)}</span>{/if}{#if net.description}<div class="text-xs text-ink-3">{net.description}</div>{/if}</td><td class="py-3 pr-6"><StatusChip status={net.status || null} /></td><td class="py-3 pr-6 font-mono text-xs text-ink-2">{net.neutron_net_id?.slice(0, 20) ?? '-'}...</td><td class="py-3 pr-6 font-mono text-xs text-ink-2">{net.neutron_subnet_id?.slice(0, 20) ?? '-'}...</td><td class="py-3 pr-6 text-xs text-ink-3">{net.created_at ? net.created_at.split('T')[0] : '-'}</td><td class="py-3 text-right"><button onclick={() => onDelete(net.id, net.name)} disabled={deleting === net.id} class="text-red-400 hover:text-red-300 disabled:text-ink-3 text-xs px-2 py-1 rounded border border-red-900 hover:border-red-700 disabled:border-line-2 transition-colors">{deleting === net.id